const toMessages = (
  client: WhatsAppClient,
  msg: InboundMessage
): WhatsAppMessage[] => {
  const base = {
    sender: { id: msg.from },
    space: { id: msg.from },
    timestamp: msg.timestamp,
  };
  if (msg.content.type === "contacts") {
    const multi = msg.content.contacts.length > 1;
    return msg.content.contacts.map((card, index) => ({
      ...base,
      id: multi ? `${msg.id}:${index}` : msg.id,
