import { ServerError } from "nice-grpc";
import { Status } from "nice-grpc-common";
import { config } from "../config";

const baseUrl = `${config.metaApiBaseUrl}/${config.metaApiVersion}`;

function metaHeaders(accessToken: string, json = true): HeadersInit {
  const headers: Record<string, string> = {
    Authorization: `Bearer ${accessToken}`,
  };
  if (json) {
    headers["Content-Type"] = "application/json";
  }
  return headers;
}

function mapHttpToGrpcStatus(status: number): Status {
  switch (status) {
    case 400:
      return Status.INVALID_ARGUMENT;
    case 401:
      return Status.UNAUTHENTICATED;
    case 403:
      return Status.PERMISSION_DENIED;
    case 404:
      return Status.NOT_FOUND;
    case 429:
      return Status.RESOURCE_EXHAUSTED;
    default:
      return Status.INTERNAL;
  }
}

async function metaFetch(
  url: string,
  accessToken: string,
  init?: RequestInit
): Promise<unknown> {
  // Never force JSON onto a FormData body: an explicit Content-Type would
  // suppress fetch's multipart boundary and Meta couldn't parse the form.
  const json = init?.method !== "DELETE" && !(init?.body instanceof FormData);
  const res = await fetch(url, {
    ...init,
    headers: {
      ...metaHeaders(accessToken, json),
      ...(init?.headers as Record<string, string>),
    },
  });

  if (!res.ok) {
    const body = await res.json().catch(() => ({}));
    const err = (body as { error?: { message?: string } }).error;
    throw new ServerError(
      mapHttpToGrpcStatus(res.status),
      err?.message ?? `Meta API error: ${res.status}`
    );
  }

  return res.json();
}

// ---------------------------------------------------------------------------
// Messages
// ---------------------------------------------------------------------------

export async function sendMessage(
  accessToken: string,
  phoneNumberId: string,
  payload: Record<string, unknown>
): Promise<{ messageId: string; messageStatus: string }> {
  const data = (await metaFetch(
    `${baseUrl}/${phoneNumberId}/messages`,
    accessToken,
    {
      method: "POST",
      body: JSON.stringify({
        messaging_product: "whatsapp",
        ...payload,
      }),
    }
  )) as {
    messages: Array<{ id: string; message_status: string }>;
  };

  return {
    messageId: data.messages[0].id,
    messageStatus: data.messages[0].message_status,
  };
}

export async function markRead(
  accessToken: string,
  phoneNumberId: string,
  messageId: string
): Promise<void> {
  await metaFetch(`${baseUrl}/${phoneNumberId}/messages`, accessToken, {
    method: "POST",
    body: JSON.stringify({
      messaging_product: "whatsapp",
      status: "read",
      message_id: messageId,
    }),
  });
}

// ---------------------------------------------------------------------------
// Media
// ---------------------------------------------------------------------------

export async function uploadMedia(
  accessToken: string,
  phoneNumberId: string,
  file: Uint8Array,
  mimeType: string,
  filename?: string
): Promise<string> {
  const formData = new FormData();
  formData.append("messaging_product", "whatsapp");
  formData.append("type", mimeType);
  formData.append(
    "file",
    new Blob([file as BlobPart], { type: mimeType }),
    filename ?? "file"
  );

  const data = (await metaFetch(
    `${baseUrl}/${phoneNumberId}/media`,
    accessToken,
    {
      method: "POST",
      body: formData,
      headers: { Authorization: `Bearer ${accessToken}` },
    }
  )) as { id: string };

  return data.id;
}

export async function getMediaUrl(
  accessToken: string,
  mediaId: string
): Promise<{
  url: string;
  mimeType: string;
  fileSize: number;
  sha256: string;
}> {
  const data = (await metaFetch(`${baseUrl}/${mediaId}`, accessToken)) as {
    url: string;
    mime_type: string;
    file_size: number;
    sha256: string;
  };

  return {
    url: data.url,
    mimeType: data.mime_type,
    fileSize: data.file_size,
    sha256: data.sha256,
  };
}

/**
 * Fetch media bytes from a lookaside.fbsbx.com URL. Returns the raw upstream
 * Response (including non-2xx) so the caller can stream the body and mirror
 * status/headers; an optional Range header is forwarded for partial content.
 */
export async function fetchMediaBytes(
  accessToken: string,
  url: string,
  range?: string
): Promise<Response> {
  const headers: Record<string, string> = {
    Authorization: `Bearer ${accessToken}`,
  };
  if (range) {
    headers.Range = range;
  }
  return fetch(url, { headers });
}

export async function deleteMedia(
  accessToken: string,
  mediaId: string
): Promise<void> {
  await metaFetch(`${baseUrl}/${mediaId}`, accessToken, { method: "DELETE" });
}

