import type { CallContext } from "nice-grpc-common";
import { registerStream } from "../cloud/connection-registry";
import { config } from "../config";
import { subscribeByo, subscribeCloud } from "../events/bus";
import { fetchEventsAfterCursor } from "../events/store";
import type {
  FetchMissedEventsRequest,
  FetchMissedEventsResponse,
  MarkReadRequest,
  MarkReadResponse,
  MessageServiceImplementation,
  SendMessageRequest,
  SendMessageResponse,
  SubscribeEventsRequest,
  SubscribeEventsResponse,
} from "../generated/photon/whatsapp/v1/message_service";
import { markRead, sendMessage } from "../meta/client";
import { processUnverifiedWebhooks } from "../secrets/process-unverified";
import { getCredentials, getProjectId } from "./credentials";
import { mapSendRequestToMeta } from "./send-mapper";

type Subscription = ReturnType<typeof subscribeByo>;

function openSubscription(
  context: CallContext,
  creds: ReturnType<typeof getCredentials>
): { subscription: Subscription; abortSignal?: AbortSignal } {
  if (creds.appSecret) {
    return {
      subscription: subscribeByo(creds.phoneNumberId, creds.appSecret),
    };
  }
  const projectId = getProjectId(context);
  if (!projectId) {
    throw new Error("Cloud mode subscription missing projectId");
  }
  const ac = registerStream(projectId);
  return {
    subscription: subscribeCloud(creds.phoneNumberId, projectId),
    abortSignal: ac.signal,
  };
}

export const messageHandler: MessageServiceImplementation = {
  async sendMessage(
    request: SendMessageRequest,
    context: CallContext
  ): Promise<SendMessageResponse> {
    const creds = getCredentials(context);
    const payload = mapSendRequestToMeta(request);
    const result = await sendMessage(
      creds.accessToken,
      creds.phoneNumberId,
      payload
    );
    return {
      messageId: result.messageId,
      messageStatus: result.messageStatus,
    };
  },

  async markRead(
    request: MarkReadRequest,
    context: CallContext
  ): Promise<MarkReadResponse> {
    const creds = getCredentials(context);
    await markRead(creds.accessToken, creds.phoneNumberId, request.messageId);
    return {};
  },

  async *subscribeEvents(
    _request: SubscribeEventsRequest,
    context: CallContext
  ): AsyncGenerator<SubscribeEventsResponse> {
    const creds = getCredentials(context);
    const { subscription, abortSignal } = openSubscription(context, creds);

    // Lifecycle logs exist so a dead consumer is diagnosable from THIS
    // service's logs alone — the folk-prod zombie-stream incident required
    // cross-referencing another service's logs to see the stream had died.
    const mode = creds.appSecret ? "byo" : "cloud";
    const projectId = getProjectId(context);
    const openedAtMs = Date.now();
    let closeReason = "client-closed";
    console.log(
      `[subscribe] stream open mode=${mode} phone_number_id=${creds.phoneNumberId}${projectId ? ` project_id=${projectId}` : ""}`
    );

    const abortPromise = abortSignal
      ? new Promise<"aborted">((resolve) => {
          if (abortSignal.aborted) {
            resolve("aborted");
            return;
          }
          abortSignal.addEventListener("abort", () => resolve("aborted"), {
            once: true,
          });
        })
      : undefined;

    try {
      const iterator = subscription[Symbol.asyncIterator]();

      // Hold a single pending iterator.next() across heartbeat loops.
      // Async generators resolve the OLDEST pending next() call first, so
      // we must reuse the same promise until we actually consume its value
      // — otherwise events get resolved to an abandoned promise and lost.
      const nextEvent = (): Promise<SubscribeEventsResponse | "done"> =>
        iterator.next().then((r) => (r.done ? "done" : r.value));
      let pendingNext = nextEvent();

      while (true) {
        let heartbeatTimer: ReturnType<typeof setTimeout> | undefined;
        const heartbeatPromise = new Promise<"heartbeat">((resolve) => {
          heartbeatTimer = setTimeout(
            () => resolve("heartbeat"),
            config.heartbeatIntervalMs
          );
        });

        const racers: Promise<
          SubscribeEventsResponse | "heartbeat" | "done" | "aborted"
        >[] = [pendingNext, heartbeatPromise];
        if (abortPromise) {
          racers.push(abortPromise);
        }

        const result = await Promise.race(racers);

        if (result !== "heartbeat" && heartbeatTimer) {
          clearTimeout(heartbeatTimer);
        }

        if (result === "done" || result === "aborted") {
          closeReason = result === "done" ? "bus-closed" : "platform-disabled";
          break;
        }
        if (result === "heartbeat") {
          yield { cursor: undefined, heartbeat: {} };
          continue; // keep pendingNext — do NOT call iterator.next() again
        }

        yield result;
        pendingNext = nextEvent();
      }
    } finally {
      subscription.close();
      console.log(
        `[subscribe] stream closed mode=${mode} phone_number_id=${creds.phoneNumberId}${projectId ? ` project_id=${projectId}` : ""} reason=${closeReason} duration_ms=${Date.now() - openedAtMs}`
      );
    }
  },

  async fetchMissedEvents(
    request: FetchMissedEventsRequest,
    context: CallContext
  ): Promise<FetchMissedEventsResponse> {
    const creds = getCredentials(context);

    // Retroactively verify any queued webhooks against the BYO secret. Cloud
    // mode doesn't use the queue (the tech-provider secret is always present).
    if (creds.appSecret) {
      await processUnverifiedWebhooks(creds.phoneNumberId, creds.appSecret);
    }

    if (!request.cursor) {
      return { events: [] };
    }

    const rows = await fetchEventsAfterCursor(
      creds.phoneNumberId,
      request.cursor.value,
      request.limit ?? 100
    );

    const events = rows.map((row) => {
      const stored = row.payload as Record<string, unknown>;
      return {
        cursor: { value: row.cursor },
        message: stored.message as SubscribeEventsResponse["message"],
        status: stored.status as SubscribeEventsResponse["status"],
      };
    });

    return { events };
  },
};

