import { expect, test } from "bun:test";
import { uploadMedia } from "../src/meta/client";

// Meta rejects media uploads whose multipart body it can't parse with
// "(#100) The parameter messaging_product is required", so assert on the
// request exactly as Meta would receive it.
test("uploadMedia sends a parseable multipart body with messaging_product", async () => {
  const originalFetch = globalThis.fetch;
  let captured: Request | undefined;
  globalThis.fetch = ((input: string | URL | Request, init?: RequestInit) => {
    captured = new Request(input, init);
    return Promise.resolve(Response.json({ id: "media-123" }));
  }) as typeof fetch;

  try {
    const mediaId = await uploadMedia(
      "test-token",
      "15550001111",
      new Uint8Array([1, 2, 3]),
      "image/png",
      "pic.png"
    );

    expect(mediaId).toBe("media-123");
    if (!captured) {
      throw new Error("fetch was never called");
    }
    expect(captured.headers.get("authorization")).toBe("Bearer test-token");
    expect(captured.headers.get("content-type")).toStartWith(
      "multipart/form-data; boundary="
    );

    const form = await captured.formData();
    expect(form.get("messaging_product")).toBe("whatsapp");
    expect(form.get("type")).toBe("image/png");
    const file = form.get("file");
    expect(file).toBeInstanceOf(Blob);
    expect(new Uint8Array(await (file as Blob).arrayBuffer())).toEqual(
      new Uint8Array([1, 2, 3])
    );
  } finally {
    globalThis.fetch = originalFetch;
  }
});

